use std::io::Write as _;
use std::net::TcpListener;
use std::net::TcpStream;
use std::sync::Arc;
use std::sync::Mutex;
use std::sync::OnceLock;
use std::time::Duration;
use std::time::Instant;

use serde_json::Value;
use serde_json::json;

use protonwire_api::AuthenticationApi as _;
use protonwire_api::Fido2Challenge;
use protonwire_api::Fido2Payload;
use protonwire_api::ForkSelector;
