use protonwire_api::LoginStep;
use protonwire_api::auth::MemorySessionStore;
use protonwire_api::auth::MuonAuth;
use protonwire_api::runtime::EngineBridge as _;
use protonwire_api::runtime::TokioBridge;

// ===========================================================================
// The std HTTP/1.1 responder with scripted, computable responses
// ===========================================================================

/// One recorded request.
#[derive(Debug, Clone)]
struct Recorded {
    method: String,
    path: String,
    headers: Vec<(String, String)>,
    body: Vec<u8>,
}

impl Recorded {
    fn header(&self, name: &str) -> Option<&str> {
        let name = name.to_ascii_lowercase();
        self.headers
            .iter()
            .find(|(k, _)| *k == name)
            .map(|(_, v)| v.as_str())
    }

    fn json(&self) -> Value {
        serde_json::from_slice(&self.body).expect("recorded body is JSON")
    }
}

/// One scripted response.
struct Response {
    status: &'static str,
    headers: Vec<(String, String)>,
    body: Vec<u8>,
}

impl Response {
    fn json(status: &'static str, body: Value) -> Self {
        Self {
            status,
            headers: vec![("Content-Type".into(), "application/json".into())],
            body: serde_json::to_vec(&body).expect("serialize scripted body"),
        }
    }

    fn error(status: &'static str, code: u16, message: &str) -> Self {
        Self::json(status, json!({"Code": code, "Error": message}))
    }

    fn empty(status: &'static str) -> Self {
        Self {
            status,
            headers: Vec::new(),
            body: Vec::new(),
        }
    }
}

/// One exchange: serve `respond(&recorded)` for the request matching
/// `method`/`path` (the responder serves steps strictly in order and
/// asserts each request matches its step).
struct Step {
    method: &'static str,
    path: String,
    respond: Box<dyn Fn(&Recorded) -> Response + Send>,
}

impl Step {
    fn static_json(
        method: &'static str,
        path: impl Into<String>,
        status: &'static str,
        body: Value,
    ) -> Self {
        Self {
            method,
            path: path.into(),
            respond: Box::new(move |_| Response::json(status, body.clone())),
        }
    }

    fn computed(
        method: &'static str,
        path: impl Into<String>,
        respond: impl Fn(&Recorded) -> Response + Send + 'static,
    ) -> Self {
        Self {
            method,
            path: path.into(),
            respond: Box::new(respond),
        }
    }
}

/// Serves the script sequentially over KEEP-ALIVE connections: the
/// client's whole exchange (anonymous-session mint, SRP handshake, 2FA,
/// ...) rides the one pooled HTTP/1.1 connection Muon's pool maintains —
/// exactly how the real API is spoken. A new connection is accepted
/// only when the client opens one (e.g. a resend after a scripted
/// error). Bounded waits so an unexpected stall fails the test instead
/// of hanging it.
///
/// (Why not `Connection: close` per exchange, the way a naive responder
/// does it: closing under Muon's pooled sender triggers its
/// channel-closed retry path, whose redial stalls under the sync
/// adapter's foreign-thread `block_on` drive — observed as a 30 s
/// timeout with the retry connecting only at teardown. Keeping the
/// pooled connection alive avoids that path entirely and matches the
/// production wire.)
fn spawn_scripted(
    steps: Vec<Step>,
) -> (std::thread::JoinHandle<()>, u16, Arc<Mutex<Vec<Recorded>>>) {
    const ACCEPT_TIMEOUT: Duration = Duration::from_secs(30);
    const IO_TIMEOUT: Duration = Duration::from_secs(30);

    let listener = TcpListener::bind("127.0.0.1:0").expect("bind loopback");
    let port = listener.local_addr().unwrap().port();
    let recorded = Arc::new(Mutex::new(Vec::new()));
    let seen = Arc::clone(&recorded);
    let handle = std::thread::spawn(move || {
        listener
            .set_nonblocking(true)
            .expect("responder nonblocking");
        let mut steps = steps.into_iter().peekable();
        'script: loop {
            if steps.peek().is_none() {
                break 'script;
            }
            // Wait for a connection (bounded poll; the client may still
            // be on the previous one, so this is not the only path).
            let waited = Instant::now();
            let mut stream = 'accept: loop {
                match listener.accept() {
                    Ok((stream, _)) => break 'accept stream,
                    Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                        if waited.elapsed() > ACCEPT_TIMEOUT {
                            break 'script;
                        }
                        std::thread::sleep(Duration::from_millis(5));
                    }
                    Err(e) => panic!("responder accept failed: {e}"),
                }
            };
            stream.set_nonblocking(false).expect("blocking stream");
            stream.set_read_timeout(Some(IO_TIMEOUT)).unwrap();
            stream.set_write_timeout(Some(IO_TIMEOUT)).unwrap();
            // Serve as many steps as the client pipelines onto this
            // connection; close when it closes or a read times out.
            while steps.peek().is_some() {
                let step = steps.next().expect("peeked");
                match read_request(&mut stream) {
                    Ok(recorded) => serve_exchange(&mut stream, step, recorded, &seen),
                    Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => break,
                    Err(e) if e.kind() == std::io::ErrorKind::UnexpectedEof => break,
                    Err(e) => panic!("responder read failed: {e}"),
                }
            }
        }
    });
    (handle, port, recorded)
}

/// Reads one request (headers + Content-Length body) from the live
/// connection.
fn read_request(stream: &mut TcpStream) -> std::io::Result<Recorded> {
    let mut buf: Vec<u8> = Vec::with_capacity(1024);
    let mut chunk = [0u8; 8192];
    let header_end;
    loop {
        if let Some(pos) = find_terminator(&buf) {
            header_end = pos;
            break;
        }
        let n = stream.read(&mut chunk)?;
        if n == 0 {
            return Err(std::io::Error::new(
                std::io::ErrorKind::UnexpectedEof,
                "connection closed between requests",
            ));
        }
        buf.extend_from_slice(&chunk[..n]);
    }
    let head = String::from_utf8_lossy(&buf[..header_end]).into_owned();
    let mut lines = head.split("\r\n");
    let request_line = lines.next().unwrap_or_default().to_owned();
    let (method, path) = match request_line.split_once(' ') {
        Some((m, rest)) => (
            m.to_owned(),
            rest.split(' ').next().unwrap_or_default().to_owned(),
        ),
        None => (String::new(), String::new()),
    };
    let headers: Vec<(String, String)> = lines
        .filter_map(|line| line.split_once(':'))
        .map(|(k, v)| (k.to_ascii_lowercase(), v.trim().to_owned()))
        .collect();
    let content_length = headers
        .iter()
        .find(|(k, _)| k == "content-length")
        .and_then(|(_, v)| v.parse::<usize>().ok())
        .unwrap_or(0);
    let mut body = buf[header_end..].to_vec();
    while body.len() < content_length {
        let n = stream.read(&mut chunk)?;
        if n == 0 {
            break;
        }
        body.extend_from_slice(&chunk[..n]);
    }
    body.truncate(content_length);
    Ok(Recorded {
        method,
        path,
        headers,
        body,
    })
}

/// Serves one scripted response on the live keep-alive connection.
fn serve_exchange(
    stream: &mut TcpStream,
    step: Step,
    recorded: Recorded,
    seen: &Mutex<Vec<Recorded>>,
) {
    assert_eq!(
        recorded.method, step.method,
        "scripted step order: expected {} {}, got {} {}",
        step.method, step.path, recorded.method, recorded.path
    );
    assert_eq!(
        recorded.path, step.path,
        "scripted step order: expected {} {}",
        step.method, step.path
    );
    let response = (step.respond)(&recorded);
    seen.lock().unwrap().push(recorded);
    let mut out = format!(
        "HTTP/1.1 {}\r\nContent-Length: {}\r\n",
        response.status,
        response.body.len()
    );
    for (k, v) in &response.headers {
        out.push_str(&format!("{k}: {v}\r\n"));
    }
    out.push_str("\r\n");
    stream
        .write_all(out.as_bytes())
        .expect("responder write head");
    stream
        .write_all(&response.body)
        .expect("responder write body");
    stream.flush().expect("responder flush");
}

fn find_terminator(buf: &[u8]) -> Option<usize> {
    buf.windows(4).position(|w| w == b"\r\n\r\n").map(|p| p + 4)
}

// ===========================================================================
// The real SRP server half (proton-srp — muon's own SRP implementation)
// ===========================================================================

/// Proton's public signed SRP modulus, recorded verbatim from
/// `GET /auth/v4/modulus` (the same class of recorded fixture as the S6
/// catalog fixture). The pinned client verifies this PGP-signed message
/// against Proton's embedded key; a fabricated modulus would fail
/// verification, so the recorded one is load-bearing for a REAL exchange.
const MODULUS_RESPONSE: &str = include_str!("../testdata/signed_modulus.json");

fn signed_modulus() -> &'static str {
    static SIGNED: OnceLock<String> = OnceLock::new();
    SIGNED.get_or_init(|| {
        serde_json::from_str::<Value>(MODULUS_RESPONSE)
            .expect("recorded modulus fixture parses")
            .get("Modulus")
            .and_then(Value::as_str)
            .expect("Modulus field")
            .to_owned()
    })
}

/// Extracts the base64 modulus from the cleartext-signed PGP message
/// (payload between the armor headers, dash-escapes removed).
fn modulus_b64(signed: &str) -> String {
    let body = signed
        .split_once("\n\n")
        .expect("armored message header")
        .1
        .split("-----BEGIN PGP SIGNATURE")
        .next()
        .expect("signature block")
        .trim();
    body.lines()
        .map(|line| line.strip_prefix("- ").unwrap_or(line))
        .collect::<Vec<_>>()
        .join("")
}

/// A fresh 10-byte salt (b64), fixed per run: the verifier and the
/// scripted `/auth/v4/info` response must agree on it.
const SRP_SALT: &str = "Jl54BOeNTVl8Ng==";

/// The SRP server state for one scripted login: the verifier Proton
/// would store for the user, and the live server interaction issuing
/// challenges and verifying proofs.
struct SrpServer {
    interaction: Mutex<proton_srp::ServerInteraction>,
}

impl SrpServer {
    /// Registers `username`/`password` the way the API would: derive the
    /// verifier with the client-side helper over the same signed modulus
    /// and salt the scripted info response serves.
    fn register(username: &str, password: &str) -> Self {
        let verifier = proton_srp::SRPAuth::generate_verifier(
            &proton_srp::RPGPVerifier::default(),
            password,
            Some(SRP_SALT),
            signed_modulus(),
        )
        .expect("generate SRP verifier");
        assert_eq!(verifier.version, proton_srp::PROTON_SRP_VERSION);
        let verifier_b64 = proton_srp::SRPVerifierB64::from(verifier).verifier;
        let raw_modulus = proton_srp::RawSRPModulus::new(&modulus_b64(signed_modulus()))
            .expect("recorded modulus is a valid 256-byte SRP modulus");
        let client_verifier =
            proton_srp::ServerClientVerifier::new(&verifier_b64).expect("verifier shape");
        let interaction = proton_srp::ServerInteraction::new(&raw_modulus, &client_verifier)
            .expect("server interaction");
        let _ = username;
        Self {
            interaction: Mutex::new(interaction),
        }
    }

    /// `/auth/v4/info`: issue the server ephemeral.
    fn challenge(&self) -> String {
        self.interaction
            .lock()
            .unwrap()
            .generate_challenge()
            .encode_b64()
    }

    /// `/auth/v4`: verify the client's proof; the server proof on
    /// success, `None` on a wrong password (the API answers 400).
    fn verify(&self, recorded: &Recorded) -> Option<String> {
        let body = recorded.json();
        let proof = proton_srp::ServerClientProof::new(
            body["ClientEphemeral"].as_str()?,
            body["ClientProof"].as_str()?,
        )
        .ok()?;
        self.interaction
            .lock()
            .unwrap()
            .verify_proof(&proof)
            .ok()
            .map(|proof| proof.encode_b64())
    }
}

// ===========================================================================
// Scripted response bodies (muon-rest wire shapes, spike memo Q1/Q2)
// ===========================================================================

const ANON_UID: &str = "anon-uid-0001";
const ANON_TOKEN: &str = "anon-token-0001";
const USER_UID: &str = "user-uid-0002";
const USER_ID: &str = "user-id-0003";
const ACCESS_TOKEN: &str = "access-token-0004";
const REFRESH_TOKEN: &str = "refresh-token-0005";

fn anon_session() -> Value {
    json!({
        "UID": ANON_UID,
        "UserID": null,
        "AccessToken": ANON_TOKEN,
        "RefreshToken": format!("{ANON_TOKEN}-refresh"),
        "Scopes": ["unauth"],
    })
}

fn auth_info(session_id: &str, ephemeral: String) -> Value {
    json!({
        "SRPSession": session_id,
        "Version": 4,
        "Salt": SRP_SALT,
        "Modulus": signed_modulus(),
        "ServerEphemeral": ephemeral,
    })
}

fn auth_v4(server_proof: String, scopes: &[&str], tfa: Value) -> Value {
    json!({
        "ServerProof": server_proof,
        "PasswordMode": 1,
        "UID": USER_UID,
        "UserID": USER_ID,
        "AccessToken": ACCESS_TOKEN,
        "RefreshToken": REFRESH_TOKEN,
        "Scopes": scopes,
        "2FA": tfa,
    })
}

fn tfa_none() -> Value {
    json!({"Enabled": 0})
}
fn tfa_totp() -> Value {
    json!({"Enabled": 1})
}

const FIDO_CHALLENGE_BYTES: [u8; 8] = [0xde, 0xad, 0xbe, 0xef, 1, 2, 3, 4];
const FIDO_CREDENTIAL_ID_BYTES: [u8; 4] = [9, 8, 7, 6];

fn tfa_fido() -> Value {
    json!({
        "Enabled": 2,
        "FIDO2": {
            "AuthenticationOptions": {
                "publicKey": {
                    "challenge": FIDO_CHALLENGE_BYTES.to_vec(),
                    "allowCredentials": [
                        {"type": "public-key", "id": FIDO_CREDENTIAL_ID_BYTES.to_vec()}
                    ],
                }
            },
            "RegisteredKeys": [
                {
                    "AttestationFormat": "packed",
                    "CredentialID": FIDO_CREDENTIAL_ID_BYTES.to_vec(),
                    "Name": "test-key",
                }
            ],
        }
    })
}

fn fido_options_json() -> Value {
    tfa_fido()["FIDO2"]["AuthenticationOptions"].clone()
}

fn refresh_response(new_access: &str, new_refresh: &str) -> Value {
    json!({
        "UID": USER_UID,
        "UserID": USER_ID,
        "AccessToken": new_access,
        "RefreshToken": new_refresh,
        "Scopes": ["loggedin", "full"],
    })
}

fn fork_get_response(uid: &str, user_id: &str) -> Value {
    json!({
        "Payload": null,
        "UID": uid,
        "UserID": user_id,
        "AccessToken": "fork-access-token",
        "RefreshToken": "fork-refresh-token",
        "Scopes": ["loggedin"],
    })
}

// ===========================================================================
// The loopback environment and the adapter harness
// ===========================================================================

/// The custom environment: direct-class loopback `http://` servers
/// (spike memo Q3 — `Scheme::Http` skips TLS).
#[derive(Debug, Clone)]
struct LoopbackEnv {
    servers: Vec<muon::common::Server>,
}

impl muon::env::Env for LoopbackEnv {
    fn servers(&self, _version: &muon::app::AppVersion) -> Vec<muon::common::Server> {
        self.servers.clone()
    }
    fn ar_pins(&self) -> Option<&muon::tls::pins::TlsPinSet> {
        None
    }
    fn api_pins(&self) -> Option<&muon::tls::pins::TlsPinSet> {
        None
    }
}

fn loopback_env(port: u16) -> muon::Environment {
    let server: muon::common::Server = format!("http://127.0.0.1:{port}/")
        .parse()
        .expect("loopback server url");
    muon::Environment::new_custom(LoopbackEnv {
        servers: vec![server],
    })
}

fn two_direct_servers_env(dead_port: u16, live_port: u16) -> muon::Environment {
    let servers: Vec<muon::common::Server> = [
        format!("http://127.0.0.1:{dead_port}/"),
        format!("http://127.0.0.1:{live_port}/"),
    ]
    .iter()
    .map(|url| url.parse().expect("loopback server url"))
    .collect();
    muon::Environment::new_custom(LoopbackEnv { servers })
}

fn adapter_against(env: muon::Environment) -> MuonAuth {
    let app = muon::App::new("linux-vpn@1.0.0").expect("app version");
    MuonAuth::connect(app, env, "protonwire").expect("adapter")
}

fn adapter_on_port(port: u16) -> MuonAuth {
    adapter_against(loopback_env(port))
}

/// A port nothing listens on.
fn dead_port() -> u16 {
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let port = listener.local_addr().unwrap().port();
    drop(listener);
    port
}

// ===========================================================================
// The scripted state-machine steps
// ===========================================================================

const USERNAME: &str = "visionary-user";
const PASSWORD: &str = "correct-horse-battery";

/// The login exchange with a REAL SRP server half: the same
/// `ServerInteraction` issues the `/auth/v4/info` challenge and verifies
/// the `/auth/v4` proof, exactly as the API would.
fn srp_login_steps(scopes: &'static [&'static str], tfa: Value) -> Vec<Step> {
    srp_login_steps_as(USERNAME, PASSWORD, scopes, tfa)
}

/// The login exchange for ARBITRARY credentials (the peer-secret pin
/// uses its own values so the SRP math is real for them too).
fn srp_login_steps_as(
    username: &str,
    password: &str,
    scopes: &'static [&'static str],
    tfa: Value,
) -> Vec<Step> {
    let server = Arc::new(SrpServer::register(username, password));
    let server_for_info = Arc::clone(&server);
    let server_for_auth = Arc::clone(&server);
    vec![
        // The anonymous-session mint muon performs before the first
        // send on a credential-less session (spike memo Q2).
        Step::static_json("POST", "/auth/v4/sessions", "200 OK", anon_session()),
        Step::computed("POST", "/auth/v4/info", move |_| {
            let ephemeral = server_for_info.challenge();
            Response::json("200 OK", auth_info("srp-session-1", ephemeral))
        }),
        Step::computed("POST", "/auth/v4", move |recorded| {
            match server_for_auth.verify(recorded) {
                Some(server_proof) => {
                    Response::json("200 OK", auth_v4(server_proof, scopes, tfa.clone()))
                }
                None => Response::error(
                    "400 Bad Request",
                    8002,
                    "incorrect password (real SRP proof verification failed)",
                ),
            }
        }),
    ]
}

fn two_factor_step() -> Step {
    Step::static_json(
        "POST",
        "/auth/v4/2fa",
        "200 OK",
        json!({"Scopes": ["loggedin", "full"]}),
    )
}

// ===========================================================================
// The wire tests
// ===========================================================================

/// SRP success end to end: the real client proof is generated by pinned
/// proton-srp, verified by the scripted API's real server interaction,
/// and the returned server proof is verified by the client — the only
/// way this step completes is a genuine SRP exchange. The trait object
/// coercion proves the adapter keeps the `&dyn` seam idiom.
#[test]
fn srp_login_success_round_trips_a_real_exchange() {
    let (handle, port, seen) = spawn_scripted(srp_login_steps(&["loggedin", "full"], tfa_none()));
    let adapter = adapter_on_port(port);

    let api: &dyn protonwire_api::AuthenticationApi = &adapter;
    let step = api.begin_login(USERNAME, PASSWORD).expect("login");
    handle.join().expect("responder thread");

    assert_eq!(
        step,
        LoginStep::Session(protonwire_api::SessionInfo {
            user_id: USER_ID.to_owned(),
            session_id: USER_UID.to_owned(),
        })
    );
    assert_eq!(api.login_status().unwrap(), LoginStatus::LoggedIn);

    let requests = seen.lock().unwrap();
    assert_eq!(
        requests
            .iter()
            .map(|r| (r.method.as_str(), r.path.as_str()))
            .collect::<Vec<_>>(),
        vec![
            ("POST", "/auth/v4/sessions"),
            ("POST", "/auth/v4/info"),
            ("POST", "/auth/v4"),
        ],
        "mint + SRP handshake order"
    );
    // The real transport's headers traveled: app version and the
    // minted anonymous bearer authorize the SRP sends.
    assert!(requests[2].header("x-pm-appversion").is_some());
    assert_eq!(
        requests[2].header("authorization"),
        Some("Bearer anon-token-0001"),
        "the minted anonymous session must authorize the auth send"
    );
    assert_eq!(requests[2].header("x-pm-uid"), Some(ANON_UID));
}

#[test]
fn fresh_adapter_reports_logged_out() {
    let (handle, port, _seen) = spawn_scripted(Vec::new());
    let adapter = adapter_on_port(port);
    handle.join().expect("responder thread");
    assert_eq!(adapter.login_status().unwrap(), LoginStatus::LoggedOut);
}

/// Wrong password: the REAL server-side proof verification fails, the
/// API answers 400, and the adapter surfaces a transport-class error
/// with the upstream detail (stable-code territory; never a panic).
#[test]
fn srp_wrong_password_fails_with_transport_error() {
    let (handle, port, _seen) = spawn_scripted(srp_login_steps(&["loggedin", "full"], tfa_none()));
    let adapter = adapter_on_port(port);

    let err = adapter
        .begin_login(USERNAME, "wrong-password")
        .expect_err("wrong password must fail");
    handle.join().expect("responder thread");

    match err {
        protonwire_api::ApiError::Transport(report) => assert!(!report.is_empty()),
        other => panic!("expected Transport failure, got {other:?}"),
    }
}

/// The 2FA challenge → TOTP round trip: the challenge descriptors are
/// Muon's typed `TFA`, reduced to the client-facing shape; the submitted
/// code travels as the `TwoFactorCode` arm; the completion reports the
/// identity the LOGIN flow observed (Muon's 2FA response carries scopes
/// only).
#[test]
fn two_factor_totp_round_trip() {
    let (handle, port, seen) = spawn_scripted(
        srp_login_steps(&["twofactor"], tfa_totp())
            .into_iter()
            .chain([two_factor_step()])
            .collect(),
    );
    let adapter = adapter_on_port(port);

    let step = adapter.begin_login(USERNAME, PASSWORD).expect("login");
    assert_eq!(
        step,
        LoginStep::Challenge(protonwire_api::Challenge {
            totp_enabled: true,
            fido2: None,
        })
    );
    let completed = adapter.submit_two_factor("123456").expect("2fa");
    handle.join().expect("responder thread");

    assert_eq!(
        completed,
        LoginStep::Session(protonwire_api::SessionInfo {
            user_id: USER_ID.to_owned(),
            session_id: USER_UID.to_owned(),
        })
    );
    assert_eq!(adapter.login_status().unwrap(), LoginStatus::LoggedIn);

    let requests = seen.lock().unwrap();
    let tfa_request = requests.last().expect("2fa request recorded");
    assert_eq!(tfa_request.path, "/auth/v4/2fa");
    assert_eq!(
        tfa_request.json()["TwoFactorCode"],
        "123456",
        "the TOTP arm must carry the code as TwoFactorCode"
    );
}

/// The 2FA challenge → FIDO2 round trip: the reduced challenge carries
/// the WebAuthn request options' challenge and allowed credentials; the
/// submitted assertion travels as the `FIDO2` arm with the ORIGINAL
/// `AuthenticationOptions` echoed (reconstructed by the adapter from the
/// challenge Muon delivered, not fabricated).
#[test]
fn two_factor_fido_round_trip() {
    let (handle, port, seen) = spawn_scripted(
        srp_login_steps(&["twofactor"], tfa_fido())
            .into_iter()
            .chain([two_factor_step()])
            .collect(),
    );
    let adapter = adapter_on_port(port);

    let step = adapter.begin_login(USERNAME, PASSWORD).expect("login");
    assert_eq!(
        step,
        LoginStep::Challenge(protonwire_api::Challenge {
            totp_enabled: false,
            fido2: Some(Fido2Challenge {
                challenge: FIDO_CHALLENGE_BYTES.to_vec(),
                allow_credentials: vec![FIDO_CREDENTIAL_ID_BYTES.to_vec()],
            }),
        })
    );

    let payload = Fido2Payload {
        client_data: "client-data-b64".into(),
        authenticator_data: "authenticator-data-b64".into(),
        signature: "signature-b64".into(),
        credential_id: FIDO_CREDENTIAL_ID_BYTES.to_vec(),
    };
    let completed = adapter.submit_fido_payload(&payload).expect("2fa fido");
    handle.join().expect("responder thread");

    assert_eq!(
        completed,
        LoginStep::Session(protonwire_api::SessionInfo {
            user_id: USER_ID.to_owned(),
            session_id: USER_UID.to_owned(),
        })
    );

    let requests = seen.lock().unwrap();
    let tfa_request = requests.last().expect("2fa request recorded");
    let body = tfa_request.json();
    assert_eq!(body["FIDO2"]["ClientData"], "client-data-b64");
    assert_eq!(body["FIDO2"]["AuthenticatorData"], "authenticator-data-b64");
    assert_eq!(body["FIDO2"]["Signature"], "signature-b64");
    assert_eq!(
        body["FIDO2"]["CredentialID"],
        json!(FIDO_CREDENTIAL_ID_BYTES)
    );
    assert_eq!(
        body["FIDO2"]["AuthenticationOptions"],
        fido_options_json(),
        "the original challenge options must be echoed, not fabricated"
    );
}

