/// FR-7C envelope bridge: the credentials this adapter observed
/// serialize EXACTLY into the store-side versioned envelope and
/// round-trip back into Muon's own type — the two crates provably
/// persist the same wire shape.
#[test]
fn observed_credentials_round_trip_through_the_session_envelope() {
    let (handle, port, _seen) = spawn_scripted(srp_login_steps(&["loggedin", "full"], tfa_none()));
    let adapter = adapter_on_port(port);
    adapter.begin_login(USERNAME, PASSWORD).expect("login");
    handle.join().expect("responder thread");

    let credentials = adapter
        .observed_credentials()
        .expect("internal credentials observed");
    let value = serde_json::to_value(&credentials).expect("muon serialization");
    let envelope = protonwire_store::session::SessionEnvelope::new(value).expect("envelope");

    let dir = TempDirGuard::new("envelope");
    let store =
        protonwire_store::session::SessionEnvelopeStore::new(dir.path().join("session.json"));
    store.save(&envelope).expect("persist");
    let loaded = store.load().expect("load").expect("present");

    let restored: muon::SessionCredentials =
        serde_json::from_value(loaded.credentials().clone()).expect("back into muon's type");
    assert_eq!(restored.access_token(), ACCESS_TOKEN);
    assert_eq!(restored.refresh_token(), REFRESH_TOKEN);
    assert_eq!(restored.uid(), USER_UID);
    assert_eq!(restored.user_id(), Some(USER_ID));
}

/// A per-test temp directory removed on drop (rust Low, S4 round: the
/// plain std fallback leaked a `pw-s4-envelope-*` directory per run —
/// panic-safe now too, which a trailing `remove_dir_all` call was not).
struct TempDirGuard(std::path::PathBuf);

impl TempDirGuard {
    fn new(tag: &str) -> Self {
        let dir = std::env::temp_dir().join(format!(
            "pw-s4-{tag}-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        Self(dir)
    }

    fn path(&self) -> &std::path::Path {
        &self.0
    }
}

impl Drop for TempDirGuard {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

// ===========================================================================
// The peer-secret registry-blindness pin (S1's finding-10 gate)
// ===========================================================================

/// One mid-call scrub observation taken INSIDE a responder step
/// closure: (field label, the value checked, whether the global scrub
/// registry redacted it). Assertions happen on the TEST thread after
/// the exchange — a panic inside the responder thread would only
/// surface as an unrelated transport failure.
type ScrubObservation = (&'static str, String, bool);

/// Records a mid-call scrub check of `value`: scrubbing to anything
/// other than itself means the value was REGISTERED — exactly what the
/// peer-secret front door forbids for wire-supplied credentials. The
/// check runs while the adapter call is blocked on the response, the
/// one window a mutated registration's handle is provably live (the qa
/// M2/M4 survivors: post-call asserts run after the registry prunes a
/// dropped handle, and the fido submission was never driven at all).
fn observe_midcall_scrub(
    seen: &Arc<Mutex<Vec<ScrubObservation>>>,
    label: &'static str,
    value: &str,
) {
    let leaked = protonwire_core::redact::scrub(value).as_ref() != value;
    seen.lock().unwrap().push((label, value.to_owned(), leaked));
}

/// The SRP login exchange with mid-call scrub checks at the
/// `/auth/v4/info` step — the first credential-bearing response, served
/// WHILE `begin_login` is blocked on it.
fn srp_login_steps_checked(
    username: &str,
    password: &str,
    scopes: &'static [&'static str],
    tfa: Value,
    midcall: &Arc<Mutex<Vec<ScrubObservation>>>,
) -> Vec<Step> {
    let server = Arc::new(SrpServer::register(username, password));
    let server_for_info = Arc::clone(&server);
    let server_for_auth = Arc::clone(&server);
    let check_user = (Arc::clone(midcall), username.to_owned());
    let check_pass = (Arc::clone(midcall), password.to_owned());
    vec![
        // The anonymous-session mint muon performs before the first
        // send on a credential-less session (spike memo Q2).
        Step::static_json("POST", "/auth/v4/sessions", "200 OK", anon_session()),
        Step::computed("POST", "/auth/v4/info", move |_| {
            // MID-CALL: begin_login is blocked on this response, so its
            // peer-secret handles (or a mutation's registered ones) are
            // live RIGHT NOW — the window the old post-call-only pin
            // could not see into.
            observe_midcall_scrub(&check_user.0, "username", &check_user.1);
            observe_midcall_scrub(&check_pass.0, "password", &check_pass.1);
            let ephemeral = server_for_info.challenge();
            Response::json("200 OK", auth_info("srp-session-1", ephemeral))
        }),
        Step::computed("POST", "/auth/v4", move |recorded| {
            match server_for_auth.verify(recorded) {
                Some(server_proof) => {
                    Response::json("200 OK", auth_v4(server_proof, scopes, tfa.clone()))
                }
                None => Response::error(
                    "400 Bad Request",
                    8002,
                    "incorrect password (real SRP proof verification failed)",
                ),
            }
        }),
    ]
}

/// The 2FA step with mid-call scrub checks — served WHILE
/// `submit_fido_payload` is blocked on it (the M4 survivor fix: the
/// old pin never drove this call at all).
fn two_factor_fido_step_checked(
    client_data: &str,
    authenticator_data: &str,
    signature: &str,
    midcall: &Arc<Mutex<Vec<ScrubObservation>>>,
) -> Step {
    let midcall = Arc::clone(midcall);
    let cd = client_data.to_owned();
    let ad = authenticator_data.to_owned();
    let sig = signature.to_owned();
    Step::computed("POST", "/auth/v4/2fa", move |_| {
        // MID-CALL: submit_fido_payload's assertion handles are live
        // right now.
        observe_midcall_scrub(&midcall, "fido-client-data", &cd);
        observe_midcall_scrub(&midcall, "fido-authenticator-data", &ad);
        observe_midcall_scrub(&midcall, "fido-signature", &sig);
        Response::json("200 OK", json!({"Scopes": ["loggedin", "full"]}))
    })
}

/// The S4 wire path's contract, pinned: every credential-shaped value
/// that arrives through the trait stays OUT of the global scrub registry
/// (peer storage only), while the one secret the adapter MINTS (a fork
/// selector, local provenance) IS registered. A future handler writing
/// `register_secret(peer.expose())` or `SecretString::new(wire_value)`
/// breaks this test.
///
/// Blindness fix (qa P2, mutation-proven M2/M4 survivors): the old pin
/// asserted only AFTER the calls — a mutated registration whose handle
/// dropped at call end was pruned from the registry before the assert
/// ran, and the FIDO submission was never driven at all. Now every
/// credential-bearing call is observed MID-CALL inside its responder
/// step closure (the handle-live window), the fido submission is
/// driven, and the post-call asserts remain for the persistent-guard
/// mutation shape. The S1 flood + local-asset arms are mirrored at the
/// wire seam beside the real exchanges.
#[test]
fn wire_supplied_credentials_never_enter_the_scrub_registry() {
    let username = "peerpin-username-value";
    let password = "peerpin-password-value";
    let fido_client_data = "peerpin-fido-client-data";
    let fido_authenticator_data = "peerpin-fido-authenticator-data";
    let fido_signature = "peerpin-fido-signature";
    let imported_selector = "peerpin-imported-selector";
    let minted_selector = "peerpin-minted-selector";
    let midcall: Arc<Mutex<Vec<ScrubObservation>>> = Arc::new(Mutex::new(Vec::new()));

    // One exchange carrying three credential-bearing calls, every one
    // observed WHILE the adapter is inside the call: begin_login
    // (checked at /auth/v4/info), submit_fido_payload (checked at
    // /auth/v4/2fa), and fork — which mints the LOCAL-provenance asset
    // the flood arm below leans on.
    let (handle, port, _seen) = spawn_scripted(
        srp_login_steps_checked(username, password, &["twofactor"], tfa_fido(), &midcall)
            .into_iter()
            .chain([two_factor_fido_step_checked(
                fido_client_data,
                fido_authenticator_data,
                fido_signature,
                &midcall,
            )])
            .chain([Step::static_json(
                "POST",
                "/auth/v4/sessions/forks",
                "200 OK",
                json!({"Selector": minted_selector}),
            )])
            .collect(),
    );
    let adapter = adapter_on_port(port);
    adapter.begin_login(username, password).expect("login");
    adapter
        .submit_fido_payload(&Fido2Payload {
            client_data: fido_client_data.into(),
            authenticator_data: fido_authenticator_data.into(),
            signature: fido_signature.into(),
            credential_id: FIDO_CREDENTIAL_ID_BYTES.to_vec(),
        })
        .expect("2fa fido");
    let selector = adapter.fork("localagent").expect("fork");
    handle.join().expect("responder thread");
    assert_eq!(selector.as_str(), minted_selector);

    // An imported selector is peer-derived too: a second exchange,
    // observed mid-call at its GET step as well.
    let import_midcall = Arc::clone(&midcall);
    let import_selector_value = imported_selector.to_owned();
    let (handle, port, _seen) = spawn_scripted(vec![Step::computed(
        "GET",
        format!("/auth/v4/sessions/forks/{imported_selector}"),
        move |_| {
            // MID-CALL: import_fork is blocked on this response.
            observe_midcall_scrub(&import_midcall, "imported-selector", &import_selector_value);
            Response::json("200 OK", fork_get_response("forked-uid-2", "forked-user-2"))
        },
    )]);
    let importer = adapter_on_port(port);
    importer
        .import_fork(&ForkSelector::new(imported_selector))
        .expect("import");
    handle.join().expect("responder thread");

    // MID-CALL verdicts — the M2/M4 fix: every observation ran while a
    // mutated registration's handle would have been live, so a
    // peer_secret -> register_secret mutation fails HERE, not after
    // the registry prunes the dropped handle.
    for (label, value, leaked) in midcall.lock().unwrap().iter() {
        assert!(
            !leaked,
            "mid-call ({label}): a wire-supplied credential was registered \
             for scrubbing DURING the call: {value}"
        );
    }

    // POST-CALL defense: the values stayed out of the registry after
    // the calls too (kills the persistent-guard mutation shape, where
    // the handle is kept alive past the call).
    for value in [
        username,
        password,
        fido_client_data,
        fido_authenticator_data,
        fido_signature,
        imported_selector,
    ] {
        assert_eq!(
            protonwire_core::redact::scrub(value),
            value,
            "a wire-supplied credential must never be registered for scrubbing"
        );
    }

    // The minted selector IS registered (local provenance — contrast
    // every peer value above): the adapter's guard keeps it scrubbable
    // for the adapter's lifetime, which is what the flood arm leans on.
    assert_eq!(
        protonwire_core::redact::scrub(minted_selector),
        protonwire_core::redact::REDACTED
    );

    // The S1 flood + local-asset arms (core pins them at the unit;
    // this mirrors both at the wire seam, beside real exchanges): 4096
    // junk values flood the exact front door every wire-supplied
    // credential crosses — none may enter the registry — and the
    // PRE-REGISTERED local asset must stay exactly as scrubbable after
    // the flood as before it (weak-ref registry, no cap to poison).
    let flood: Vec<_> = (0..4096)
        .map(|i| protonwire_core::redact::peer_secret(format!("peerpin-junk-{i:06}")))
        .collect();
    for peer in flood.iter().step_by(256) {
        assert_eq!(
            protonwire_core::redact::scrub(peer.expose()),
            peer.expose(),
            "a flooded peer value must never be registered"
        );
    }
    assert_eq!(
        protonwire_core::redact::scrub(minted_selector),
        protonwire_core::redact::REDACTED,
        "the pre-registered local asset must stay scrubbable after the flood"
    );
}

// ===========================================================================
// The real-Muon canary arm (m2-plan S1/S4): muon's REAL auth code paths
// driven offline with canary values as live credentials
// ===========================================================================

/// A fingerprint provider carrying a canary value (the real
/// `muon::common::auth` "setting fingerprint" site fires during the
/// anonymous-session mint when a provider supplies one).
#[derive(Debug, Clone)]
struct CanaryFingerprint(muon::Fingerprint);

impl muon::ProvideInformation for CanaryFingerprint {
    fn fingerprint(&self) -> Option<muon::Fingerprint> {
        Some(self.0.clone())
    }
}

/// The real-muon emitter. What runs per assertion level — all REAL muon
/// 2.6.1 code, offline, against the loopback responder:
///
/// 1. `Client::builder(..).build()` — the real hyper transport over the
///    real tokio OS/runtime pieces (production `protonwire_api::runtime`).
/// 2. Anonymous-session mint with a fingerprint provider (real
///    `muon::common::auth`: "setting fingerprint {canary}").
/// 3. `Session::auth().login(canary, canary)` — the real SRP login
///    (real `muon::auth::login`: username, SRP session id, uid fields,
///    `%auth` Display; real `muon::store` Auth Debug).
/// 4. `LoginTwoFactorFlow::totp(canary)` — the REAL TOTP-at-info site
///    the PRD's FR-7P claim names, with the canary code as the live
///    credential. (Driven on the flow object directly: the adapter's
///    trait arm refuses non-TOTP-shaped input, and a canary value is
///    deliberately not TOTP-shaped.)
/// 5. `Client::get_session(missing-canary-key)` — the real
///    `muon::client` session-key site.
/// 6. `AuthFlow::from_fork().with_selector(canary)` — the real
///    `muon::auth::from_fork` selector sites (twice at info per the S0
///    memo), as the FR-7L import path.
/// 7. A scripted `Set-Cookie` response header carrying the cookie
///    canary (sec rider, S4 round). PREMISE CORRECTED during landing:
///    at pinned muon 2.6.1 the retry handler's DEBUG site formats the
///    response through `Display` (`received http::Response { status,
///    error_code }` — no headers), so no Set-Cookie value reaches any
///    writer even with the `muon::common::retry` cap removed; the step
///    is therefore an engine-upgrade TRAP, not a currently
///    load-bearing pin — every canary run now pushes a secret-shaped
///    response header through the real transport and the real retry
///    handler, so a future muon that logs response headers (e.g. by
///    switching to `{res:?}`, whose Debug DOES carry the full
///    HeaderMap — res.rs:59-67) turns this arm red at exactly the
///    levels the cap guards. Mutation-verified while landing: with the
///    cap entry neutralized to TRACE the arm stayed green and the
///    captured writer showed the Display shape verbatim.
///
/// Disclosure — the one site NOT driven: pvpnclient's
/// `supervisor::localagent` trace (fork selector + cookies). pvpnclient
/// is a protun transitive and is not linked into this crate's test
/// binary; its site remains covered by the S1 stub arm, which injects
/// every canary class through every site including that one.
///
/// FINDINGS — this arm's first two catches, both UNKNOWN to the S0
/// memo's Q9 table and therefore to the S1 stub arm (the stub can only
/// replay the memo's sites; driving real muon found more):
///
/// 1. `muon::transport::http::req` logs the whole request at `warn`
///    ("is using the default time constraint self=GET
///    /auth/v4/sessions/forks/{selector}") — and the fork selector
///    RIDES THE PATH, so the selector class reaches the writer at
///    EVERY allowed runtime level through a module the S1 caps do not
///    name.
/// 2. `muon::transport::http::hyper::sender` (and its `http1` sibling)
///    log full request objects INCLUDING BODIES at `debug`
///    (`sending request with hyper req=Request { .., body: Body {
///    data: Some(b"{\"TwoFactorCode\":\"...\"}") } }`) — every
///    credential that travels a request body (username, TOTP, FIDO
///    assertions, refresh tokens, the fingerprint payload) leaks at
///    debug/trace.
///
/// Scrubbing cannot cover either site (peer-derived values must never
/// enter the registry), and before-formatting suppression for them
/// lives in `crates/core/src/redact.rs` — the S1 lane's file, not this
/// lane's. RESOLVED: the fix — `("muon::transport", Level::ERROR)` in
/// `MODULE_CAPS` — was validated against this exact arm, reported, and
/// landed by the S1 lane at 29a90b5 (with the stub arm extended to
/// replay both new sites). The arm below runs GREEN at all five levels
/// as the permanent real-muon regression pin; if a future engine
/// upgrade moves a leak outside the capped subtrees, this arm is what
/// catches it.
struct RealMuonCanaryEmitter;

impl protonwire_core::redact::canary::CanaryEmitter for RealMuonCanaryEmitter {
    fn name(&self) -> &'static str {
        "muon-2.6.1"
    }

    fn emit(&self, c: &protonwire_core::redact::canary::Canaries) {
        use muon::auth::LoginFlow;
        use protonwire_api::runtime::TokioOs;
        use protonwire_api::runtime::TokioSpawner;
        use protonwire_api::runtime::os_prng;

        // Owned canary values: the step closures and the single async
        // scope below are 'static.
        let uid = c.uid.clone();
        let session_id = c.session_id.clone();
        let username = c.username.clone();
        let password = c.password.clone();
        let totp = c.totp.clone();
        let selector = c.selector.clone();
        let token = c.token.clone();
        let fingerprint = CanaryFingerprint(muon::Fingerprint(json!({
            "canary": c.fingerprint, "secret": c.private_key,
        })));

        let server = Arc::new(SrpServer::register(&username, &password));
        let server_for_info = Arc::clone(&server);
        let server_for_auth = Arc::clone(&server);
        let auth_uid = uid.clone();
        let auth_token = token.clone();
        let auth_token_refresh = format!("{token}-r");

        let cookie_header = c.cookie.clone();
        let anon_uid = uid.clone();
        let anon_token = token.clone();
        let anon_refresh = format!("{token}-r");

        let mut script = vec![
            // The scripted Set-Cookie step (item 7 above): a real
            // response header carrying the cookie canary through the
            // real transport and the real retry handler on every
            // canary run (see the premise correction — a trap for
            // engines that start logging response headers).
            Step::computed("POST", "/auth/v4/sessions", move |_| {
                let body = serde_json::to_vec(&json!({
                    "UID": anon_uid, "UserID": null,
                    "AccessToken": anon_token, "RefreshToken": anon_refresh,
                    "Scopes": ["unauth"],
                }))
                .expect("serialize scripted body");
                Response {
                    status: "200 OK",
                    headers: vec![
                        ("Content-Type".into(), "application/json".into()),
                        (
                            "Set-Cookie".into(),
                            format!("Session-Id={cookie_header}; Path=/; Secure; HttpOnly"),
                        ),
                    ],
                    body,
                }
            }),
            Step::computed("POST", "/auth/v4/info", move |_| {
                Response::json(
                    "200 OK",
                    json!({
                        "SRPSession": session_id, "Version": 4,
                        "Salt": SRP_SALT, "Modulus": signed_modulus(),
                        "ServerEphemeral": server_for_info.challenge(),
                    }),
                )
            }),
            Step::computed("POST", "/auth/v4", move |recorded| {
                match server_for_auth.verify(recorded) {
                    Some(proof) => Response::json(
                        "200 OK",
                        json!({
                            "ServerProof": proof, "PasswordMode": 1,
                            "UID": auth_uid, "UserID": auth_uid,
                            "AccessToken": auth_token, "RefreshToken": auth_token_refresh,
                            "Scopes": ["twofactor"], "2FA": {"Enabled": 1},
                        }),
                    ),
                    None => Response::error("400 Bad Request", 8002, "canary password rejected"),
                }
            }),
            Step::static_json(
                "POST",
                "/auth/v4/2fa",
                "200 OK",
                json!({"Scopes": ["loggedin", "full"]}),
            ),
        ];
        script.push(Step::static_json(
            "GET",
            format!("/auth/v4/sessions/forks/{selector}"),
            "200 OK",
            json!({
                "Payload": null, "UID": c.session_id, "UserID": c.username,
                "AccessToken": c.token, "RefreshToken": format!("{}-r", c.token),
                "Scopes": ["loggedin"],
            }),
        ));
        let (handle, port, _seen) = spawn_scripted(script);

        let bridge = TokioBridge::dedicated().expect("canary runtime");
        let server_url: muon::common::Server = format!("http://127.0.0.1:{port}/")
            .parse()
            .expect("loopback url");
        let env = muon::Environment::new_custom(LoopbackEnv {
            servers: vec![server_url],
        });
        let app = muon::App::new("linux-vpn@1.0.0").expect("app");
        let store = MemorySessionStore::new();
        let missing_session_key = format!("missing-{}", c.session_id);

        // One async scope owning everything: the REAL client build, the
        // real login with canary credentials, the real 2FA site, the
        // real session-key site, and the real from_fork selector sites.
        bridge.block_on(Box::pin(async move {
            let client = muon::Client::builder(app, env)
                .with_operating_system(TokioOs::default(), os_prng().expect("entropy"))
                .with_multi_thread_executor(TokioSpawner)
                .with_persistence(store)
                .with_info_provider(fingerprint)
                .without_cookie_store()
                .build()
                .expect("canary muon client");

            let session = client
                .new_session_without_credentials("canary".to_owned())
                .await
                .expect("canary session");
            let flow = session.auth().login(&username, &password).await;
            let two_factor = match flow {
                LoginFlow::TwoFactor(flow, _) => flow,
                other => panic!("canary login must reach the 2FA stage, got {other:?}"),
            };
            // The REAL TOTP site with the canary code as the live value.
            let logged_in = two_factor.totp(totp).await.expect("canary 2fa");
            drop(logged_in);

            // The real muon::client session-key site.
            let _ = client.get_session(missing_session_key).await;

            // The real muon::auth::from_fork selector sites.
            let child = client
                .new_session_without_credentials("child".to_owned())
                .await
                .expect("child session");
            let imported = child.auth().from_fork().with_selector(selector).await;
            drop(imported);
        }));

        handle.join().expect("canary responder thread");
    }
}

/// T-32, real arm: every canary class driven through muon's real auth
/// code paths — login, TOTP, store, fingerprint, session keys, and the
/// from_fork selector flow — must reach NO captured writer at ANY
/// allowed runtime level, and the suppressed modules' events must never
/// be formatted at all. Reuses `assert_no_secrets_reach_logs`
/// unchanged (m2-plan S1).
///
/// RED-TO-GREEN HISTORY: this arm first ran red, catching two
/// transport-layer disclosure sites the S0 memo.s Q9 table missed
/// (see the emitter documentation above); the fix — one MODULE_CAPS
/// entry — was validated against this exact arm and landed by the S1
/// lane at 29a90b5 (`("muon::transport", Level::ERROR)`); the arm is
/// green at all five levels since and stays in the suite as the
/// permanent real-muon regression pin.
#[test]
fn t32_real_muon_arm_no_secret_class_reaches_any_writer() {
    protonwire_core::redact::canary::assert_no_secrets_reach_logs(&RealMuonCanaryEmitter);
}
